using System.Collections.Generic;
using UnityEngine;
[DefaultExecutionOrder(1800)]
public sealed class MountainParallaxBackdrop:MonoBehaviour{
 sealed class State{public LayeredParallaxBackground.Layer layer;public Sprite sprite;public Material original,material;public float phase=.5f,tileWidth,worldHeight;public bool sky;}
 readonly List<State> layers=new List<State>();LayeredParallaxBackground configuration;static Sprite quad;float previousX;
 void Awake(){configuration=GetComponent<LayeredParallaxBackground>();var template=Resources.Load<Material>("MountainParallax");if(configuration==null||template==null){enabled=false;return;}configuration.enabled=false;var camera=configuration.cam!=null?configuration.cam:Camera.main;float referenceH=camera!=null?camera.orthographicSize*2:16;previousX=camera!=null?camera.transform.position.x:0;
 if(quad==null)quad=Sprite.Create(Texture2D.whiteTexture,new Rect(0,0,Texture2D.whiteTexture.width,Texture2D.whiteTexture.height),Vector2.one*.5f,Texture2D.whiteTexture.width,0,SpriteMeshType.FullRect);
 for(int i=0;i<configuration.layers.Count;i++){var l=configuration.layers[i];var r=l.renderer;if(r==null||r.sprite==null)continue;var s=new State{layer=l,sprite=r.sprite,original=r.sharedMaterial,material=new Material(template),sky=i==0};float coverage=configuration.heightCoverage*(l.fullScreen?Mathf.Max(1.12f,l.heightScale):l.heightScale);s.worldHeight=referenceH*coverage;s.tileWidth=s.sprite.bounds.size.x/s.sprite.bounds.size.y*s.worldHeight*l.widthScale;Rect rect=s.sprite.rect;var tex=s.sprite.texture;s.material.SetTexture("_SourceTex",tex);s.material.SetVector("_Rect",new Vector4((rect.xMin+.5f)/tex.width,(rect.yMin+.5f)/tex.height,(rect.xMax-.5f)/tex.width,(rect.yMax-.5f)/tex.height));s.material.SetFloat("_Sky",s.sky?1:0);s.material.SetFloat("_Repeat",i==1?0:1);s.material.SetFloat("_Extend",i==configuration.layers.Count-1?1:0);r.sprite=quad;r.sharedMaterial=s.material;r.drawMode=SpriteDrawMode.Simple;r.sortingOrder=configuration.baseSortingOrder+i;layers.Add(s);}}
 void LateUpdate(){var cam=configuration!=null&&configuration.cam!=null?configuration.cam:Camera.main;if(cam==null)return;Vector3 c=cam.transform.position;float h=cam.orthographicSize*2,w=h*cam.aspect,dx=c.x-previousX;previousX=c.x;bool visible=c.x>=configuration.visibleCameraX.x&&c.x<=configuration.visibleCameraX.y;foreach(var s in layers){var l=s.layer;var r=l.renderer;if(r==null)continue;r.enabled=visible;if(!visible)continue;s.phase+=(dx*(1-l.factor)-Time.deltaTime*l.driftSpeed)/Mathf.Max(1,s.tileWidth);float height=s.sky?1.12f:s.worldHeight/h;float bottom=l.fullScreen?.5f-height*.5f:.5f+configuration.verticalOffset-height*.5f+l.verticalShift;s.material.SetVector("_Layout",new Vector4(s.sky?.5f:s.phase,s.sky?1:w/s.tileWidth,bottom,height));r.transform.position=new Vector3(c.x,c.y,r.transform.position.z);r.transform.localScale=new Vector3(w*1.04f,h*1.04f,1);}}
 void OnDestroy(){foreach(var s in layers){if(s.layer.renderer!=null){s.layer.renderer.sprite=s.sprite;s.layer.renderer.sharedMaterial=s.original;}if(s.material!=null)Destroy(s.material);}}
}
